priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
dist[s]=0; pq.push({0,s});
while(!pq.empty()){ auto [d,u]=pq.top(); pq.pop(); if(d!=dist[u]) continue; for(auto [v,w]:g[u]) if(dist[v]>d+w) dist[v]=d+w, pq.push({dist[v],v}); }

